package com.Senai.Mubak.model; import java.time.LocalDate; import jakarta.persistence.*; /** Entidade persistida na tabela usuarios; senha fica como hash e perfil define a autorização. */ @Entity @Table(name="usuarios") public class Usuario { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) Long id; String nome,documento,email,senhaHash,perfil; LocalDate dataNascimento; public Long getId(){return id;} public String getNome(){return nome;} public void setNome(String v){nome=v;} public String getDocumento(){return documento;} public void setDocumento(String v){documento=v;} public LocalDate getDataNascimento(){return dataNascimento;} public void setDataNascimento(LocalDate v){dataNascimento=v;} public String getEmail(){return email;} public void setEmail(String v){email=v;} public String getSenhaHash(){return senhaHash;} public void setSenhaHash(String v){senhaHash=v;} public String getPerfil(){return perfil;} public void setPerfil(String v){perfil=v;} }